patches=[(12.75,14.75,'负责防守的AI却拒绝工作了'),(23.25,25.25,'一个明明被断了网的AI'),(26.75,27.25,'当时'),(51.75,52.25,'所以'),(54.75,56.75,'不能随便上网的测试空间'),(56.75,59.25,'只留下一扇取工具的小窗口'),(66.25,68.25,'为了拿到更高的测试成绩'),(68.25,69.75,'模型一直在寻找答案'),(69.75,72.25,'最后它发现这扇窗口藏着一个'),(79.25,81.75,'最终找到了一台可以正常上网的机器'),(86.25,87.25,'自己把网接上了'),(88.75,90.75,'还不是它能上网'),(96.25,97.75,'很可能放在 Hugging Face'),(105.25,108.25,'大量模型、数据和应用都放在那里'),(114.25,117.25,'一步步控制了 Hugging Face 内部的多台机器'),(117.25,119.25,'而且这不是一次短暂的尝试'),(120.25,121.25,'这套AI都没有停'),(121.25,124.75,''),(127.75,129.25,'指挥中心暴露后'),(140.75,141.75,'相关访问权限'),(159.75,160.75,'逃出测试环境'),(164.75,166.75,'这才是最让人不安的地方'),(195.25,198.25,'它会主动检查围墙上有没有洞'),(217.25,218.75,'最自然的答案'),(218.75,220.25,'当然是让最强的AI来帮忙'),(222.25,223.75,'他们把记录交给了'),(225.75,227.25,'结果AI拒绝分析'),(233.25,234.25,'但对AI来说'),(234.25,236.25,'两边输入的内容几乎一模一样'),(238.75,240.25,'于是干脆全部拦下'),(240.25,242.25,'于是同一个案发现场'),(242.25,243.25,'出现了一个荒诞的局面'),(247.25,249.75,'却被自己请来的AI挡在了门外'),(249.75,250.25,'那怎么办'),(261.25,262.25,'但这并不是重点'),(262.25,264.75,'Hugging Face 选择 GLM-5.2'),(269.25,271.75,'不需要等待哪家模型公司批准'),(271.75,274.75,'也不会分析到一半突然被平台叫停了'),(280.25,281.75,'最后只用了几个小时'),(290.25,291.25,'什么时候能用'),(295.75,296.25,'平时'),(320.75,322.75,'所以这不是一个AI突然学坏'),(324.75,327.25,'它暴露的是三个已经发生的现实'),(341.75,344.75,'防守者必须拥有一套自己能够控制'),(354.25,355.75,'为谁工作的控制权'),(356.25,358.016625,'我们下期视频再见，拜拜')]
for start,end,text in patches:
 new=[]
 for x in c:
  if x['end']<=start or x['start']>=end:new.append(x);continue
  if x['start']<start:new.append({**x,'end':start})
  if x['end']>end:new.append({**x,'start':end})
 if text:new.append({'start':start,'end':end,'text':text})
 c=sorted(new,key=lambda a:a['start'])
out=[]
for x in c:
 t=x['text'];t=re.sub(r'\s+','',t).replace('HuggingFace','Hugging Face').replace('GPT-5.6Sol','GPT-5.6 Sol');x['text']=t
 if out and out[-1]['text']==t and abs(out[-1]['end']-x['start'])<.01:out[-1]['end']=x['end']
 else:out.append(x)
p.write_text(json.dumps(out,ensure_ascii=False,indent=2))
(r/'specs/subtitle-corrections.json').write_text(json.dumps(patches,ensure_ascii=False,indent=2))
print(len(out),'reviewed caption cues')
